use function Phiz\{aes, facet_wrap, geom_point, ggplot, label_dollar, labs, scale_y_continuous};

$orders = \Phiz\Data::url('/exports/orders.csv');

$plot = ggplot($orders, aes(x: 'items:Q', y: 'total:Q', color: 'channel:N')) |>
    geom_point(alpha: 0.6) |>
    facet_wrap('region', ncol: 3) |>
    scale_y_continuous(labels: label_dollar()) |>
    labs(x: 'Items', y: 'Order total', color: 'Channel');

echo $plot->toJson(pretty: true);

