use function Phiz\label_dollar;

$orders = \Phiz\Data::url('/exports/orders.csv');

$plot = \Phiz\Plot::of($orders)
    ->aes(x: 'items:Q', y: 'total:Q', color: 'channel:N')
    ->point(alpha: 0.6)
    ->facetWrap('region', ncol: 3)
    ->scaleY(labels: label_dollar())
    ->labs(x: 'Items', y: 'Order total', color: 'Channel');

echo $plot->toJson(pretty: true);

